SELECT

FROM blog_article a
JOIN sys_user u ON u.user_id = a.author_id

    JOIN blog_article_content c ON c.article_id = a.article_id




            a.status = 1
            AND a.visibility = 1
            AND a.deleted_at IS NULL
            AND a.publish_time IS NOT NULL
            AND a.publish_time <= #{filter.now}




                    a.deleted_at IS NOT NULL


                    a.deleted_at IS NULL



                AND a.author_id = #{filter.scopeAuthor}


                AND a.status = #{filter.status}


                AND a.visibility = #{filter.visibility}




        AND a.author_id = #{filter.authorId}


        AND (
            INSTR(a.title, #{filter.keyword}) > 0
            OR INSTR(a.summary, #{filter.keyword}) > 0
            OR INSTR(c.markdown_content, #{filter.keyword}) > 0
        )


        AND a.category_id = #{filter.categoryId}

            AND EXISTS (
                SELECT 1
                FROM blog_category k
                WHERE k.category_id = a.category_id
                  AND k.status = 1
            )



        AND EXISTS (
            SELECT 1
            FROM blog_article_tag t
            WHERE t.article_id = a.article_id
              AND t.tag_id = #{filter.tagId}
        )


        AND a.publish_time >= #{filter.from}


        AND a.publish_time < #{filter.until}




        ORDER BY a.is_top DESC, a.publish_time DESC, a.article_id DESC


        ORDER BY a.is_top DESC, a.update_time DESC, a.article_id DESC

